{"command":"cat <<'EOF' > /tmp/test_width.rs
fn char_width(c: char) -> usize {
    let u = c as u32;
    if u < 0x20 || (0x7F..=0x9F).contains(&u) {
        return 1; // control characters
    }
    // Combining characters
    if (0x0300..=0x036F).contains(&u)
        || (0x1DC0..=0x1DFF).contains(&u)
        || (0x20D0..=0x20FF).contains(&u)
        || (0xFE20..=0xFE2F).contains(&u)
        || u == 0x200D
        || (0xFE00..=0xFE0F).contains(&u)
        || (0xE0100..=0xE01EF).contains(&u)
    {
        return 0;
    }
    // Wide / Fullwidth / CJK / Emojis
    if (0x1100..=0x115F).contains(&u)
        || (0x2329..=0x232A).contains(&u)
        || (0x2E80..=0x303E).contains(&u)
        || (0x3040..=0xA4CF).contains(&u)
        || (0xAC00..=0xD7A3).contains(&u)
        || (0xF900..=0xFAFF).contains(&u)
        || (0xFE10..=0xFE19).contains(&u)
        || (0xFE30..=0xFE6F).contains(&u)
        || (0xFF01..=0xFF60).contains(&u)
        || (0xFFE0..=0xFFE6).contains(&u)
        || (0x20000..=0x3FFFF).contains(&u)
        || (0x1F300..=0x1F64F).contains(&u)
        || (0x1F680..=0x1F6FF).contains(&u)
        || (0x1F900..=0x1F9FF).contains(&u)
        || (0x1FA00..=0x1FAFF).contains(&u)
        || (0x2600..=0x27BF).contains(&u)
    {
        return 2;
    }
    1
}

fn str_display_width(s: &str) -> usize {
    s.lines()
        .map(|line| line.chars().map(char_width).sum::<usize>())
        .max()
        .unwrap_or(0)
}

fn main() {
    println!("width test: 'a' -> {}", char_width('a'));
    println!("width test: '中' -> {}", char_width('中'));
    println!("width test: '😀' -> {}", char_width('😀'));
    println!("width test: 'header,cjk,emoji' -> {}", str_display_width("header,cjk,emoji"));
}
EOF
