{"command":"cat <<'EOF' > /tmp/test_pager.rs
use std::env;
use std::io::IsTerminal;
use std::os::unix::io::AsRawFd;
use std::process::{Command, Stdio};

fn setup_pager(disable_pager: bool) -> Option<std::process::Child> {
    if disable_pager || !std::io::stdout().is_terminal() {
        return None;
    }
    let pager = env::var("PAGER").unwrap_or_else(|_| "less -RFX".to_string());
    if pager == "cat" || pager.is_empty() {
        return None;
    }
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(&pager)
        .stdin(Stdio::piped())
        .spawn()
        .ok()?;

    if let Some(child_stdin) = child.stdin.take() {
        let fd = child_stdin.as_raw_fd();
        unsafe {
            libc::dup2(fd, 1);
        }
        // Forget child_stdin so fd 1 remains open
        std::mem::forget(child_stdin);
    }
    Some(child)
}

fn main() {
    let mut child = setup_pager(false);
    println!("Hello from pager test!");
    for i in 1..=5 {
        println!("Row {}", i);
    }
    // Flush stdout before exiting
    use std::io::Write;
    let _ = std::io::stdout().flush();
    // Close duped stdout (fd 1) so pager gets EOF
    unsafe {
        libc::close(1);
    }
    if let Some(ref mut c) = child {
        let _ = c.wait();
    }
}
EOF
