fn truncate_str(s: &str, target_w: usize) -> &str {
    let mut current_w = 0;
    let mut end_byte = 0;
    for c in s.chars() {
        let w = char_width(c);
        if current_w + w > target_w {
            break;
        }
        current_w += w;
        end_byte += c.len_utf8();
    }
    &s[..end_byte]
