    1
}

fn str_display_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn truncate_str(s: &str, target_w: usize) -> &str {
    let mut current_w = 0;
    let mut end_byte = 0;
    for c in s.chars() {
        let w = char_width(c);
        if current_w + w > target_w {
            break;
        }
        current_w += w;
        end_byte += c.len_utf8();
    }
    &s[..end_byte]
}

struct Config {
    file: Option<String>,
    no_headers: bool,
    number: bool,
    tsv: bool,
    delimiter: Option<char>,
    style: Style,
    padding: usize,
    indent: usize,
    sniff: usize,
    header_align: Align,
    body_align: Align,
    disable_pager: bool,
}

