        bin_name
    );
}

fn print_clap_error_and_exit(msg: &str) -> ! {
    eprintln!("{}", msg);
    std::process::exit(2);
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let bin_name = args
        .get(0)
        .and_then(|s| std::path::Path::new(s).file_name()?.to_str())
        .unwrap_or("executable")
        .to_string();

    let mut config = Config {
        file: None,
        no_headers: false,
        number: false,
        tsv: false,
        delimiter: None,
        style: Style::Sharp,
        padding: 1,
        indent: 0,
        sniff: 1000,
        header_align: Align::Center,
        body_align: Align::Left,
        disable_pager: false,
    };

    let mut i = 1;
    let mut file_arg = None;

    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            print_help(&bin_name);
            std::process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("csview 1.3.4");
            std::process::exit(0);
        } else if arg == "-H" || arg == "--no-headers" {
            config.no_headers = true;
        } else if arg == "-n" || arg == "--number" {
            config.number = true;
        } else if arg == "-t" || arg == "--tsv" {
            config.tsv = true;
        } else if arg == "-P" || arg == "--disable-pager" {
            config.disable_pager = true;
        } else if arg == "-d" || arg == "--delimiter" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--delimiter <DELIMITER>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            let mut chars = val.chars();
            match (chars.next(), chars.next()) {
                (Some(c), None) => config.delimiter = Some(c),
                (None, _) => print_clap_error_and_exit(&format!(
                    "error: invalid value '' for '--delimiter <DELIMITER>': cannot parse char from empty string\n\nFor more information, try '--help'."
                )),
                _ => print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--delimiter <DELIMITER>': too many characters in string\n\nFor more information, try '--help'.",
                    val
                )),
            }
        } else if arg.starts_with("-d") {
            let val = &arg[2..];
            let mut chars = val.chars();
            match (chars.next(), chars.next()) {
                (Some(c), None) => config.delimiter = Some(c),
                (None, _) => print_clap_error_and_exit(&format!(
                    "error: invalid value '' for '--delimiter <DELIMITER>': cannot parse char from empty string\n\nFor more information, try '--help'."
                )),
                _ => print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--delimiter <DELIMITER>': too many characters in string\n\nFor more information, try '--help'.",
                    val
                )),
            }
        } else if arg == "-s" || arg == "--style" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--style <STYLE>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.style = match val.as_str() {
                "none" => Style::None,
                "ascii" => Style::Ascii,
                "ascii2" => Style::Ascii2,
                "sharp" => Style::Sharp,
                "rounded" => Style::Rounded,
                "reinforced" => Style::Reinforced,
                "markdown" => Style::Markdown,
                "grid" => Style::Grid,
                _ => print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--style <STYLE>'\n  [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]\n\nFor more information, try '--help'.",
                    val
                )),
            };
        } else if arg == "-p" || arg == "--padding" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--padding <PADDING>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.padding = val.parse().unwrap_or_else(|_| {
                print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--padding <PADDING>': invalid digit found in string\n\nFor more information, try '--help'.",
                    val
                ))
            });
        } else if arg == "-i" || arg == "--indent" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--indent <INDENT>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.indent = val.parse().unwrap_or_else(|_| {
                print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--indent <INDENT>': invalid digit found in string\n\nFor more information, try '--help'.",
                    val
                ))
            });
        } else if arg == "--sniff" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--sniff <LIMIT>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.sniff = val.parse().unwrap_or_else(|_| {
                print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--sniff <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.",
                    val
                ))
            });
        } else if arg == "--header-align" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--header-align <HEADER_ALIGN>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.header_align = match val.as_str() {
                "left" => Align::Left,
                "center" => Align::Center,
                "right" => Align::Right,
                _ => print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--header-align <HEADER_ALIGN>'\n  [possible values: left, center, right]\n\nFor more information, try '--help'.",
                    val
                )),
            };
        } else if arg == "--body-align" {
            i += 1;
            if i >= args.len() {
                print_clap_error_and_exit(&format!(
                    "error: a value is required for '--body-align <BODY_ALIGN>' but none was supplied\n\nFor more information, try '--help'."
                ));
            }
            let val = &args[i];
            config.body_align = match val.as_str() {
                "left" => Align::Left,
                "center" => Align::Center,
                "right" => Align::Right,
                _ => print_clap_error_and_exit(&format!(
                    "error: invalid value '{}' for '--body-align <BODY_ALIGN>'\n  [possible values: left, center, right]\n\nFor more information, try '--help'.",
                    val
                )),
            };
        } else if arg.starts_with('-') {
            print_clap_error_and_exit(&format!(
                "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.",
                arg, arg, arg, bin_name
            ));
        } else {
            if file_arg.is_some() {
                print_clap_error_and_exit(&format!(
                    "error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.",
                    arg, bin_name
                ));
            }
            file_arg = Some(arg.clone());
        }
        i += 1;
    }

    if config.tsv && config.delimiter.is_some() {
        print_clap_error_and_exit(&format!(
            "error: the argument '--tsv' cannot be used with '--delimiter <DELIMITER>'\n\nUsage: {} --tsv [FILE]\n\nFor more information, try '--help'.",
            bin_name
        ));
    }

    config.file = file_arg;
    config
}

fn setup_pager(disable_pager: bool) -> Option<std::process::Child> {
    if disable_pager || !io::stdout().is_terminal() {
        return None;
    }
    let pager = env::var("PAGER").unwrap_or_else(|_| "less -RFX".to_string());
    if pager == "cat" || pager.is_empty() {
        return None;
    }
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(&pager)
        .stdin(Stdio::piped())
        .spawn()
        .ok()?;

    if let Some(child_stdin) = child.stdin.take() {
        let fd = child_stdin.as_raw_fd();
        unsafe {
            dup2(fd, 1);
        }
        std::mem::forget(child_stdin);
    }
    Some(child)
}

fn parse_csv(
    bytes: &[u8],
    delimiter: char,
) -> Result<Vec<Vec<String>>, String> {
    let mut records = Vec::new();
    let mut i = 0;
    let len = bytes.len();
    let delim_byte = delimiter as u8;

    let mut line_num = 1;
    let mut rec_idx = 0;

    let mut first_field_count = None;

    if len == 0 {
        return Ok(records);
    }

    while i < len {
        // Skip carriage return / newlines for empty lines
        while i < len && (bytes[i] == b'\n' || bytes[i] == b'\r') {
            if bytes[i] == b'\n' {
                line_num += 1;
            }
            i += 1;
        }
        if i >= len {
            break;
        }

        let rec_start_byte = i;
        let rec_start_line = line_num;

        let mut fields = Vec::new();

        loop {
            if i >= len {
                fields.push(String::new());
                break;
            }

            if bytes[i] == b'"' {
                i += 1;
                let mut field_bytes = Vec::new();
                while i < len {
                    if bytes[i] == b'"' {
                        if i + 1 < len && bytes[i + 1] == b'"' {
                            field_bytes.push(b'"');
                            i += 2;
                        } else {
                            i += 1;
                            break;
                        }
                    } else {
                        if bytes[i] == b'\n' {
                            line_num += 1;
                        }
                        field_bytes.push(bytes[i]);
                        i += 1;
                    }
                }
                let s = match String::from_utf8(field_bytes) {
                    Ok(s) => s,
                    Err(e) => {
                        let utf8_err_idx = e.utf8_error().valid_up_to();
                        return Err(format!(
                            "CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                            rec_idx, rec_start_line, fields.len() + 1, rec_start_byte, fields.len() + 1, utf8_err_idx
                        ));
                    }
                };
                fields.push(s);

                while i < len && bytes[i] != delim_byte && bytes[i] != b'\n' && bytes[i] != b'\r' {
                    i += 1;
                }
                if i < len && bytes[i] == delim_byte {
                    i += 1;
                } else {
                    if i < len && bytes[i] == b'\r' {
                        i += 1;
                    }
                    if i < len && bytes[i] == b'\n' {
                        i += 1;
                        line_num += 1;
                    }
                    break;
                }
            } else {
                let mut field_bytes = Vec::new();
                while i < len && bytes[i] != delim_byte && bytes[i] != b'\n' && bytes[i] != b'\r' {
                    field_bytes.push(bytes[i]);
                    i += 1;
                }
                let s = match String::from_utf8(field_bytes) {
                    Ok(s) => s,
                    Err(e) => {
                        let utf8_err_idx = e.utf8_error().valid_up_to();
                        return Err(format!(
                            "CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                            rec_idx, rec_start_line, fields.len() + 1, rec_start_byte, fields.len() + 1, utf8_err_idx
                        ));
                    }
                };
                fields.push(s);

                if i < len && bytes[i] == delim_byte {
                    i += 1;
                } else {
                    if i < len && bytes[i] == b'\r' {
                        i += 1;
                    }
                    if i < len && bytes[i] == b'\n' {
                        i += 1;
                        line_num += 1;
                    }
                    break;
                }
            }
        }

        if let Some(expected) = first_field_count {
            if fields.len() != expected {
                return Err(format!(
                    "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                    rec_idx, rec_start_line, rec_start_byte, fields.len(), expected
                ));
            }
        } else {
            first_field_count = Some(fields.len());
        }

        records.push(fields);
        rec_idx += 1;
    }

    Ok(records)
}

fn make_border_line(
    cols: &[usize],
    pad: usize,
    indent: usize,
    parts: (&'static str, &'static str, &'static str, &'static str),
) -> String {
    let (left, dash, inter, right) = parts;
    let mut res = String::new();
    for _ in 0..indent {
        res.push(' ');
    }
    res.push_str(left);
    for (i, &w) in cols.iter().enumerate() {
        if i > 0 {
            res.push_str(inter);
        }
        let dashes_count = w + 2 * pad;
        for _ in 0..dashes_count {
            res.push_str(dash);
        }
    }
    res.push_str(right);
    res
}

fn format_row(
    row: &[String],
    col_widths: &[usize],
    align: Align,
    pad: usize,
    indent: usize,
    col_left: &str,
    col_sep: &str,
    col_right: &str,
) -> String {
    let mut res = String::new();
    for _ in 0..indent {
        res.push(' ');
    }
    res.push_str(col_left);
    for (k, val) in row.iter().enumerate() {
        if k > 0 {
            res.push_str(col_sep);
        }
        let target_w = col_widths.get(k).copied().unwrap_or(0);
        let trunc_val = truncate_str(val, target_w);
        let disp_w = str_display_width(trunc_val);
        let extra = if target_w >= disp_w { target_w - disp_w } else { 0 };

        let (l_space, r_space) = match align {
            Align::Left => (0, extra),
            Align::Right => (extra, 0),
            Align::Center => {
                let l = extra / 2;
                (l, extra - l)
            }
        };

        for _ in 0..pad {
            res.push(' ');
        }
        for _ in 0..l_space {
            res.push(' ');
        }
        res.push_str(trunc_val);
        for _ in 0..r_space {
            res.push(' ');
        }
        for _ in 0..pad {
            res.push(' ');
        }
    }
    res.push_str(col_right);
    res
}

fn main() {
    let config = parse_args();

    let delim = if config.tsv {
        '\t'
    } else {
        config.delimiter.unwrap_or(',')
    };

    let bytes = match &config.file {
        Some(path) => match fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
        },
        None => {
            let mut b = Vec::new();
            if let Err(e) = io::stdin().read_to_end(&mut b) {
                eprintln!("csview: {}", e);
                std::process::exit(1);
            }
            b
        }
    };

    let mut records = match parse_csv(&bytes, delim) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("csview: {}", e);
            std::process::exit(1);
        }
    };

    // Prepend line numbers if requested
    if config.number {
        if config.no_headers {
            for (idx, rec) in records.iter_mut().enumerate() {
                rec.insert(0, (idx + 1).to_string());
            }
        } else {
            for (idx, rec) in records.iter_mut().enumerate() {
                if idx == 0 {
                    rec.insert(0, "#".to_string());
                } else {
                    rec.insert(0, idx.to_string());
                }
            }
        }
    }

    let mut child = setup_pager(config.disable_pager);

    let has_headers = !config.no_headers;

    let num_cols = if let Some(rec) = records.first() {
        rec.len()
    } else if config.number {
        1
    } else {
        0
    };

    let mut col_widths = vec![0; num_cols];

    if records.is_empty() && config.number {
        col_widths[0] = 1;
    }

    let sniff_limit = if config.sniff == 0 {
        records.len()
    } else {
        let count = if has_headers { config.sniff + 1 } else { config.sniff };
        count.min(records.len())
    };

    for rec in records.iter().take(sniff_limit) {
        for (i, cell) in rec.iter().enumerate() {
            if i < num_cols {
                let w = str_display_width(cell);
                if w > col_widths[i] {
                    col_widths[i] = w;
                }
            }
        }
    }

    let bstyle = get_style(config.style);

    // Render table
    if has_headers {
        if let Some(header_row) = records.first() {
            if let Some(parts) = bstyle.top {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
            println!("{}", format_row(
                header_row,
                &col_widths,
                config.header_align,
                config.padding,
                config.indent,
                bstyle.col_left,
                bstyle.col_sep,
                bstyle.col_right
            ));

            let body_records = &records[1..];
            if !body_records.is_empty() {
                if let Some(parts) = bstyle.hdr {
                    println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
                }
                for (r_idx, row) in body_records.iter().enumerate() {
                    if r_idx > 0 {
                        if let Some(parts) = bstyle.row {
                            println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
                        }
                    }
                    println!("{}", format_row(
                        row,
                        &col_widths,
                        config.body_align,
                        config.padding,
                        config.indent,
                        bstyle.col_left,
                        bstyle.col_sep,
                        bstyle.col_right
                    ));
                }
            }
            if let Some(parts) = bstyle.bot {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
        } else {
            // Header requested, but 0 records
            let dummy_header = if config.number { vec!["#".to_string()] } else { vec![] };
            if let Some(parts) = bstyle.top {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
            println!("{}", format_row(
                &dummy_header,
                &col_widths,
                config.header_align,
                config.padding,
                config.indent,
                bstyle.col_left,
                bstyle.col_sep,
                bstyle.col_right
            ));
            if let Some(parts) = bstyle.bot {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
        }
    } else {
        // No headers
        if !records.is_empty() {
            if let Some(parts) = bstyle.top {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
            for (r_idx, row) in records.iter().enumerate() {
                if r_idx > 0 {
                    if let Some(parts) = bstyle.row {
                        println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
                    }
                }
                println!("{}", format_row(
                    row,
                    &col_widths,
                    config.body_align,
                    config.padding,
                    config.indent,
                    bstyle.col_left,
                    bstyle.col_sep,
                    bstyle.col_right
                ));
            }
            if let Some(parts) = bstyle.bot {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
        } else {
            if let Some(parts) = bstyle.top {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
            if let Some(parts) = bstyle.bot {
                println!("{}", make_border_line(&col_widths, config.padding, config.indent, parts));
            }
        }
    }

    let _ = io::stdout().flush();
    unsafe {
        close(1);
    }
    if let Some(ref mut c) = child {
        let _ = c.wait();
    }
}
